		this.oldFunctionSignature = function.getSignature().getPrototypeString();
	}

	protected EditFunctionSignatureDialog(PluginTool tool, string title, Function function,
			bool allowInLine, bool allowNoReturn, bool allowCallFixup) : base(tool, title, allowInLine, allowNoReturn, allowCallFixup)
    {
		this.function = function;
