		List<string> list = new();
		list.add(Function.UNKNOWN_CALLING_CONVENTION_STRING);
		list.add(Function.DEFAULT_CALLING_CONVENTION_STRING);
		list.addAll(function.getProgram().getFunctionManager().getCallingConventionNames());
