		if (allowNoReturn) {
			compoundCommand.add(new _Anon_Command_Program_3());
		}
		if (allowCallFixup) {
			compoundCommand.add(new _Anon_Command_Program_4());
		}
		if (cmd != null) {
			compoundCommand.add(cmd);
